#include "KS/SRC/stringx.h"
#define assert(x) ((void)0)

struct charstarwrap { char *str; };

struct map_node
{
  int color;
  map_node *parent;
  map_node *left;
  map_node *right;
  charstarwrap first;
  unsigned int second;
};

class name_to_number_map
{
public:
  class iterator
  {
  public:
    map_node *node;
    iterator() {}
    iterator(map_node *n) : node(n) {}
    map_node& operator*() const { return *node; }
    bool operator!=(const iterator& other) const { return node != other.node; }
    iterator& operator++()
    {
      if (node->right != 0)
      {
        node = node->right;
        while (node->left != 0)
          node = node->left;
      }
      else
      {
        map_node *parent = node->parent;
        while (node == parent->right)
        {
          node = parent;
          parent = parent->parent;
        }
        if (node->right != parent)
          node = parent;
      }
      return *this;
    }
  };

  map_node *header;
  iterator begin() { return iterator(header->left); }
  iterator end() { return iterator(header); }
};

class entity_manager
{
  char pad[16];
public:
  name_to_number_map name_to_number;
  static entity_manager *instance;
  static entity_manager *inst() { return instance; }
};
__asm__(".equ _14entity_manager$instance, 0x003E5A60");

class entity_id
{
public:
  stringx get_val() const;
private:
  unsigned int val;
};

stringx entity_id::get_val() const
{
  name_to_number_map::iterator found;

  name_to_number_map& name_to_number = entity_manager::inst()->name_to_number;
  for( found = name_to_number.begin(); found != name_to_number.end(); ++found)
  {
    if( (*found).second == val )
    {
      return stringx((*found).first.str);
    }
  }
  assert(false);
  return stringx("garbage");
}
